import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('120.', 1056, own='oth_elps.jsonl')
SP = {'20.d.1.A', '20.d.4.E'}
def H(code, d, q, right, wrong, e):
    return B.hand(code + (' ' if code in SP else ''), d, q, right, wrong, e)

# ================= K-3 (120.20) =================
# 1 Listening
H('20.d.1.A',1,"A teacher says the words ship and sheep. Which listening skill is the student using to tell them apart?","hearing the different vowel sounds",["reading the page upside down","counting the letters","drawing a picture"],"Distinguishing sounds means noticing small differences in speech.")
H('20.d.1.A',2,"A student hears a question with rising intonation at the end. What does this usually tell the listener?","The speaker is asking a question.",["The speaker is finished talking.","The speaker is whispering a secret.","The speaker is angry."],"Intonation patterns help listeners understand meaning.")
H('20.d.1.B',2,"During science class a teacher says, The seed will germinate. A student who understands content vocabulary knows germinate means:","start to grow",["fall to the ground","turn red","get washed away"],"Content-area vocabulary helps students follow lessons.")
H('20.d.1.B',2,"Which word from math class would a student need to know to follow the instruction, Find the sum?","sum",["find","the","class"],"Sum is a content-area word meaning the result of adding.")
H('20.d.1.C',1,"The teacher says, Put your pencil in the box and then stand up. What should the student do first?","put the pencil in the box",["stand up","open the door","sit down"],"Following oral directions means doing each step in order.")
H('20.d.1.C',2,"Which student is following directions with accuracy?","the student who listens to every step and does them in order",["the student who skips the middle step","the student who does the last step first","the student who talks during directions"],"Accurate direction following means listening carefully.")
H('20.d.1.D',2,"If someone says, It's raining cats and dogs, what do the words mean?","It is raining very hard.",["Animals are falling from the sky.","It is a sunny day.","Pets are playing outside."],"Figurative language is understood by using context.")
H('20.d.1.D',2,"The word bat can mean an animal or a sports tool. How can a listener tell which meaning is used?","by using the other words in the sentence",["by guessing at random","by ignoring the word","by asking nobody"],"Context clues help with words with multiple meanings.")
H('20.d.1.E',2,"After listening to a story, which shows good listening comprehension?","retelling the main events in order",["naming only the title","drawing a random shape","saying the story was long"],"Comprehension means understanding what was heard.")
H('20.d.1.E',2,"During a class discussion, a student listens and then answers the question the teacher asked. This shows:","listening comprehension",["a spelling test","a math problem","a science fair"],"Responding correctly shows understanding.")
H('20.d.1.F',2,"A student watches a short video about weather and learns new words. This is an example of getting meaning from:","auditory multimedia",["a handwritten letter","a dictionary only","a math worksheet"],"Videos and audio build vocabulary.")
H('20.d.1.F',3,"Which is an auditory multimedia source?","a recorded story played on a tablet",["a paper map","a plain worksheet","a photograph with no sound"],"Auditory means related to sound.")
# 2 Speaking
H('20.d.2.A',2,"A student practicing pronunciation sees the word knee. Which letter is not pronounced?","k",["e","n","a"],"The k in knee is not pronounced.")
H('20.d.2.A',2,"When practicing English pronunciation, which word has a long a sound like the name of the letter A?","cake",["cat","cup","cut"],"The a in cake says its name.")
H('20.d.2.B',2,"A student presents on how liquid water turns into a gas. Which word is the science vocabulary term for this?","evaporation",["very","also","then"],"Evaporation is a science term.")
H('20.d.2.B',2,"Which sentence uses a math content word correctly?","The triangle has three sides.",["The triangle can sing.","The triangle is a color.","The triangle is tasty."],"Using subject words correctly shows understanding.")
H('20.d.2.C',2,"Which connecting word joins these ideas: I like apples ___ I like pears?","and",["because of","under","behind"],"And joins two similar ideas.")
H('20.d.2.C',3,"Which sentence is a question?","Where is the library?",["The library is big.","Please be quiet.","I love books."],"Questions ask for information and end with a question mark.")
H('20.d.2.D',2,"Which greeting is best to say to a teacher?","Good morning, Ms. Lee.",["Hey, you.","What's up, dude.","Sup."],"Register means choosing words that fit the person and place.")
H('20.d.2.D',3,"Register means:","choosing language that fits the situation and listener",["the sound of a bell","a type of register in a store","spelling every word perfectly"],"Formal and informal talk are different registers.")
H('20.d.2.E',3,"Which sentence adds more detail?","The big brown dog ran quickly across the green yard.",["The dog ran.","Dog ran.","Ran dog."],"More specific words give more detail.")
H('20.d.2.E',3,"When you describe a pet to a friend, which is the best way to be specific?","say its color, size and what it likes to do",["say only the word pet","say it is nice","say nothing"],"Specific details help the listener picture it.")
H('20.d.2.F',2,"When a friend finishes explaining a game, which is a good follow-up question?","How do you win?",["I am hungry.","The sky is blue.","Close the door."],"Asking questions shows you are listening.")
