H('20.d.3.C',2,"Which English word is a cognate of the Spanish word elefante?","elephant",["horse","apple","pencil"],"Cognates look and sound similar in two languages.")
H('20.d.3.C',3,"Which is a high-frequency word that appears in many texts?","the",["photosynthesis","triangle","democracy"],"High-frequency words are common.")
H('20.d.3.D',3,"The sentence He has a heart of gold means the person is:","very kind",["made of metal","very rich in gold","sick"],"Idioms have meanings beyond the exact words.")
H('20.d.3.D',3,"What does the idiom piece of cake mean?","something very easy",["a dessert","a gift","a big problem"],"Idioms must be read using context.")
H('20.d.3.E',2,"Before reading a book, which strategy helps?","looking at the title and pictures",["closing the book","skipping to the end only","covering the pictures"],"Previewing text features gets readers ready.")
H('20.d.3.E',3,"Connecting to prior knowledge before reading means:","thinking about what you already know on the topic",["memorizing the book","reading backward","copying a friend"],"Prior knowledge supports comprehension.")
H('20.d.3.F',3,"A reader sees a bold word with a picture next to it. How can the picture help?","It gives a visual clue to the word's meaning.",["It hides the meaning.","It is a puzzle.","It means the word is wrong."],"Visual supports help understand texts.")
H('20.d.3.F',3,"Which is a contextual support that helps with an unknown word?","the sentences around the word",["the page number","the book cover color","the publisher"],"Context clues are found near the word.")
H('20.d.3.G',2,"After reading, which shows good comprehension?","retelling the story in your own words",["naming the page number","listing the font","counting the pictures"],"Retelling shows understanding.")
H('20.d.3.G',3,"Making a connection to a text means:","relating the story to your own life or another story",["changing the ending randomly","skipping chapters","copying the title"],"Connections help understanding.")
H('20.d.3.H',2,"Reading with fluency means reading:","smoothly with few mistakes",["very slowly word by word","with no expression","in a whisper only"],"Fluent readers read accurately and smoothly.")
H('20.d.3.H',3,"Which shows both fluency and comprehension?","reading a paragraph smoothly and explaining what it said",["reading fast without understanding","reading only the first word","saying numbers out loud"],"Fluency plus comprehension is the goal.")
